 	\[
 		\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 		\qquad \text{and} \qquad
 		\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 	\]
